-- =====================================================================
--  Online Vehicle Rental Management System
--  Database : vehicle_rental_db   (MySQL 8.0)
--
--  How to run:
--    1. Open MySQL Workbench, connect as root.
--    2. File > Open SQL Script > select this file.
--    3. Click the lightning-bolt icon (Execute) to run.
--
--  WARNING: Running this script DROPS and recreates vehicle_rental_db.
--           All existing data in vehicle_rental_db will be lost.
--
--  Passwords in sample data use PBKDF2 hashing (generated by the app).
--  The admin setup procedure is documented in README.md.
-- =====================================================================

DROP DATABASE IF EXISTS vehicle_rental_db;
CREATE DATABASE vehicle_rental_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE vehicle_rental_db;

-- ---------------------------------------------------------------------
-- users : customers and admins
-- ---------------------------------------------------------------------
CREATE TABLE users (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    full_name   VARCHAR(100)  NOT NULL,
    email       VARCHAR(150)  NOT NULL UNIQUE,
    password_hash VARCHAR(256) NOT NULL,
    phone       VARCHAR(15)   NOT NULL,
    role        ENUM('CUSTOMER', 'ADMIN') NOT NULL DEFAULT 'CUSTOMER',
    created_at  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,

    INDEX idx_users_email (email),
    INDEX idx_users_role  (role)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- vehicles
--   status AVAILABLE   = can be booked
--   status UNAVAILABLE = cannot be booked (maintenance, retired, etc.)
-- ---------------------------------------------------------------------
CREATE TABLE vehicles (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    name                VARCHAR(100) NOT NULL,
    brand               VARCHAR(60)  NOT NULL,
    model               VARCHAR(60)  NOT NULL,
    vehicle_type        ENUM('CAR', 'SUV', 'BIKE') NOT NULL,
    registration_number VARCHAR(20)  NOT NULL UNIQUE,
    seating_capacity    INT          NOT NULL,
    price_per_day       DECIMAL(10,2) NOT NULL,
    image_url           VARCHAR(255) DEFAULT NULL,
    description         TEXT,
    status              ENUM('AVAILABLE', 'UNAVAILABLE') NOT NULL DEFAULT 'AVAILABLE',

    INDEX idx_vehicles_type   (vehicle_type),
    INDEX idx_vehicles_status (status),
    CHECK (price_per_day > 0),
    CHECK (seating_capacity > 0)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- bookings
--   booking_status CONFIRMED = active booking
--   booking_status CANCELLED = cancelled by customer or admin
--
--   Overlap rule (enforced in application code):
--     An existing booking conflicts with a requested booking when:
--       existing.pickup_date  < requested.return_date
--       AND existing.return_date > requested.pickup_date
--     (only checked for bookings whose status is NOT 'CANCELLED')
-- ---------------------------------------------------------------------
CREATE TABLE bookings (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    user_id         INT            NOT NULL,
    vehicle_id      INT            NOT NULL,
    pickup_date     DATE           NOT NULL,
    return_date     DATE           NOT NULL,
    total_days      INT            NOT NULL,
    total_amount    DECIMAL(10,2)  NOT NULL,
    booking_status  ENUM('CONFIRMED', 'CANCELLED') NOT NULL DEFAULT 'CONFIRMED',
    created_at      TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CHECK (return_date > pickup_date),
    CHECK (total_days > 0),
    CHECK (total_amount > 0),

    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE RESTRICT,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT,

    INDEX idx_bookings_user    (user_id),
    INDEX idx_bookings_vehicle (vehicle_id),
    INDEX idx_bookings_status  (booking_status),
    INDEX idx_bookings_dates   (pickup_date, return_date)
) ENGINE=InnoDB;


